inputs.script:
$ErrorActionPreference = 'Stop'
$download = $env:SYSTEM_DEFAULTWORKINGDIRECTORY
$root = Join-Path $download '_FF_CI\testpackage'
Write-Host "Agent: $env:AGENT_NAME; release: $env:RELEASE_RELEASEID; deployment: $env:RELEASE_DEPLOYMENTID; selected CI build: $env:SELECTED_CI_BUILD_ID"
Write-Host "Expected package: $root"
foreach ($relative in @('package-info.json', 'scripts/Invoke-ReleaseStage.ps1', 'scripts/Prepare-ReleaseTestPackage.ps1', 'tools/release_reporting.py', 'tools/generate_consolidated_report.py', 'config/framework.json')) {
  if (-not (Test-Path -LiteralPath (Join-Path $root $relative) -PathType Leaf)) {
    if (Test-Path -LiteralPath $download) { Get-ChildItem -LiteralPath $download -Recurse -Depth 3 -ErrorAction SilentlyContinue | Select-Object -First 100 -ExpandProperty FullName | ForEach-Object { Write-Host $_ } }
    throw "Missing CI package file: $relative. Enable artifact download in this phase, keep alias _FF_CI, and select a new CI build containing the version-2 testpackage."
  }
}
$info = Get-Content -LiteralPath (Join-Path $root 'package-info.json') -Raw | ConvertFrom-Json
if ($info.schemaVersion -ne 2) { throw 'Unsupported package schema; select a new CI build.' }
if ($env:SELECTED_CI_BUILD_ID -notmatch '^[1-9][0-9]*$') { throw 'CI artifact alias _FF_CI is not linked to a build. Reselect the Build artifact after import.' }
if ([string]$info.buildId -ne $env:SELECTED_CI_BUILD_ID) { throw 'Package build ID differs from the selected release artifact. Refusing stale agent content.' }
if ($info.buildConfiguration -ne $env:BUILDCONFIGURATION) { throw "BuildConfiguration must match the packaged configuration: $($info.buildConfiguration)" }
Write-Host "Validated CI build $($info.buildId); branch: $($info.sourceBranch); commit: $($info.sourceVersion)"

